import { z } from "zod";
import { ApiError } from "./service";
import type { CatalogDB } from "./catalog-model.server";

const now=()=>new Date().toISOString();
const uid=(p:string)=>`${p}_${crypto.randomUUID()}`;
const clamp=(n:number,min=0,max=100)=>Math.max(min,Math.min(max,n));
async function sha256(v:string){const d=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(v));return Array.from(new Uint8Array(d),b=>b.toString(16).padStart(2,"0")).join("");}
function safe<T>(v:any,fallback:T):T{try{return JSON.parse(String(v??"")) as T}catch{return fallback}}

export type RiskDomain="buyer"|"publisher"|"community"|"payout"|"usage";
type Signal={code:string;score:number;detail?:Record<string,unknown>};

async function activePolicy(db:CatalogDB,domain:RiskDomain){
  const at=now(),row=await db.prepare("SELECT * FROM risk_policy_versions WHERE domain=? AND status='active' AND effective_from<=? AND (effective_to IS NULL OR effective_to>?) ORDER BY version DESC LIMIT 1").bind(domain,at,at).first<any>();
  if(!row)throw new ApiError(503,`No active ${domain} risk policy is configured.`);
  return{...row,policy:safe<any>(row.policy_json,{})};
}
function decisionFor(score:number,policy:any){const t=policy?.thresholds||{},block=Number(t.block??90),hold=Number(t.hold??70),challenge=Number(t.challenge??50),monitor=Number(t.monitor??25);if(score>=block)return{level:"critical",action:"block"};if(score>=hold)return{level:"high",action:"hold"};if(score>=challenge)return{level:"elevated",action:"challenge"};if(score>=monitor)return{level:"elevated",action:"monitor"};return{level:"low",action:"allow"};}

export async function recordRiskEvent(db:CatalogDB,input:{domain:RiskDomain;eventType:string;subjectType:string;subjectId:string;userId?:string|null;publishingAccountId?:string|null;orderId?:string|null;payoutItemId?:string|null;reviewId?:string|null;usageEventId?:string|null;amountMinor?:number|null;currency?:string|null;territory?:string|null;deviceFingerprintHash?:string;networkFingerprintHash?:string;paymentFingerprintHash?:string;provider?:string;providerEventId?:string;metadata?:unknown;dedupeKey:string;occurredAt?:string}){
  const id=uid("risk_evt"),at=now();await db.prepare(`INSERT OR IGNORE INTO risk_events(id,domain,event_type,subject_type,subject_id,user_id,publishing_account_id,order_id,payout_item_id,review_id,usage_event_id,amount_minor,currency,territory_code,device_fingerprint_hash,network_fingerprint_hash,payment_fingerprint_hash,provider,provider_event_id,metadata_json,dedupe_key,occurred_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,input.domain,input.eventType,input.subjectType,input.subjectId,input.userId||null,input.publishingAccountId||null,input.orderId||null,input.payoutItemId||null,input.reviewId||null,input.usageEventId||null,input.amountMinor??null,input.currency?.toUpperCase()||null,input.territory?.toUpperCase()||null,input.deviceFingerprintHash||"",input.networkFingerprintHash||"",input.paymentFingerprintHash||"",input.provider||"fore",input.providerEventId||"",JSON.stringify(input.metadata||{}),input.dedupeKey,input.occurredAt||at,at).run();return{id};
}

async function persistAssessment(db:CatalogDB,domain:RiskDomain,subjectType:string,subjectId:string,signals:Signal[],snapshot:any,providerScores:any={}){
  const policy=await activePolicy(db,domain),score=clamp(Math.round(signals.reduce((s,x)=>s+Number(x.score||0),0))),d=decisionFor(score,policy.policy),id=uid("risk_asmt"),at=now(),prior=await db.prepare("SELECT id FROM risk_assessments WHERE domain=? AND subject_type=? AND subject_id=? ORDER BY created_at DESC LIMIT 1").bind(domain,subjectType,subjectId).first<any>();
  await db.prepare("INSERT INTO risk_assessments(id,domain,subject_type,subject_id,policy_version_id,score,level,action,signals_json,provider_scores_json,input_snapshot_json,supersedes_assessment_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(id,domain,subjectType,subjectId,policy.id,score,d.level,d.action,JSON.stringify(signals),JSON.stringify(providerScores||{}),JSON.stringify(snapshot||{}),prior?.id||null,at).run();
  return{id,domain,subjectType,subjectId,score,level:d.level,action:d.action,signals,policyVersionId:policy.id};
}

async function ensureRiskCase(db:CatalogDB,a:any,opts:{publishingAccountId?:string|null;summary:string}){
  if(!["hold","block"].includes(a.action))return null;const existing=await db.prepare("SELECT id,case_number FROM risk_cases WHERE domain=? AND subject_type=? AND subject_id=? AND status NOT IN ('resolved','closed') ORDER BY opened_at DESC LIMIT 1").bind(a.domain,a.subjectType,a.subjectId).first<any>();if(existing)return existing;
  const id=uid("risk_case"),number=`FR-${new Date().getUTCFullYear()}-${crypto.randomUUID().replace(/-/g,"").slice(0,8).toUpperCase()}`,priority=a.action==="block"?"urgent":"high",at=now(),sla=new Date(Date.now()+(priority==="urgent"?4:24)*3600_000).toISOString();
  await db.prepare("INSERT INTO risk_cases(id,case_number,domain,subject_type,subject_id,assessment_id,publishing_account_id,priority,status,summary,sla_due_at,opened_at,updated_at) VALUES(?,?,?,?,?,?,?,?,'open',?,?,?,?)").bind(id,number,a.domain,a.subjectType,a.subjectId,a.id,opts.publishingAccountId||null,priority,opts.summary,sla,at,at).run();
  await db.prepare("INSERT INTO risk_case_events(id,case_id,event_type,actor_type,payload_json,created_at) VALUES(?,?,'case_opened','system',?,?)").bind(uid("risk_ce"),id,JSON.stringify({assessmentId:a.id,score:a.score,action:a.action}),at).run();return{id,case_number:number};
}

export async function createRiskHold(db:CatalogDB,a:any,scope:string,reasonCode:string,opts:{amountMinor?:number|null;currency?:string|null;publishingAccountId?:string|null;summary?:string;expiresAt?:string|null}={}){
  const active=await db.prepare("SELECT id FROM risk_holds WHERE subject_type=? AND subject_id=? AND hold_scope=? AND status='active' LIMIT 1").bind(a.subjectType,a.subjectId,scope).first<any>();if(active)return active;
  const id=uid("risk_hold"),at=now();await db.prepare("INSERT INTO risk_holds(id,assessment_id,domain,subject_type,subject_id,hold_scope,reason_code,status,amount_minor,currency,release_conditions_json,created_by_type,created_at,expires_at) VALUES(?,?,?,?,?,?,?,'active',?,?,?,'system',?,?)").bind(id,a.id,a.domain,a.subjectType,a.subjectId,scope,reasonCode,opts.amountMinor??null,opts.currency?.toUpperCase()||null,JSON.stringify({manualReview:true}),at,opts.expiresAt||null).run();await ensureRiskCase(db,a,{publishingAccountId:opts.publishingAccountId,summary:opts.summary||`${a.domain} risk ${a.action}: ${reasonCode}`});return{id};
}

export async function assessBuyerOrderRisk(db:CatalogDB,orderId:string,provider?:{riskScore?:number|null;riskLevel?:string|null;providerSignalId?:string|null}){
  const o=await db.prepare("SELECT * FROM commerce_orders WHERE id=?").bind(orderId).first<any>();if(!o)throw new ApiError(404,"Order not found for risk assessment.");const weights=(await activePolicy(db,"buyer")).policy.weights||{},signals:Signal[]=[];
  const failures=Number((await db.prepare("SELECT COUNT(*) n FROM commerce_orders WHERE user_id=? AND status='payment_failed' AND created_at>=datetime('now','-1 day')").bind(o.user_id).first<any>())?.n||0);if(failures)signals.push({code:"recent_payment_failures",score:Math.min(24,failures*Number(weights.recentPaymentFailures||8)),detail:{count:failures}});
  const hist=await db.prepare("SELECT COUNT(*) orders,SUM(CASE WHEN status IN ('refunded','partially_refunded') THEN 1 ELSE 0 END) refunds,SUM(CASE WHEN status IN ('disputed','chargeback_lost') THEN 1 ELSE 0 END) disputes FROM commerce_orders WHERE user_id=? AND created_at<>?").bind(o.user_id,o.created_at).first<any>().catch(()=>null);
  const orders=Number(hist?.orders||0),refunds=Number(hist?.refunds||0),disputes=Number(hist?.disputes||0);if(orders>=2&&refunds/orders>=.5)signals.push({code:"refund_ratio",score:Number(weights.refundRatio||35),detail:{orders,refunds}});if(disputes>0)signals.push({code:"dispute_history",score:Math.min(70,disputes*Number(weights.disputeHistory||40)),detail:{disputes}});
  const promos=Number((await db.prepare("SELECT COUNT(*) n FROM commerce_promo_redemptions WHERE user_id=? AND created_at>=datetime('now','-1 day')").bind(o.user_id).first<any>())?.n||0);if(promos>=4)signals.push({code:"promo_velocity",score:Number(weights.promoVelocity||20),detail:{count:promos}});
  if(Number(o.gift_card_minor||0)>0&&Number(o.total_minor||0)>0&&Number(o.gift_card_minor)/Number(o.total_minor)>=.8)signals.push({code:"gift_card_heavy",score:Number(weights.giftCardHeavy||15)});
  const giftReuse=await db.prepare(`SELECT COUNT(DISTINCT o2.user_id) users FROM commerce_orders o2 JOIN commerce_checkout_quotes q2 ON q2.id=o2.quote_id JOIN commerce_checkout_quotes q ON q.id=? WHERE q.gift_card_hash IS NOT NULL AND q.gift_card_hash<>'' AND q2.gift_card_hash=q.gift_card_hash AND o2.created_at>=datetime('now','-30 days')`).bind(o.quote_id).first<any>();if(Number(giftReuse?.users||0)>=4)signals.push({code:"gift_card_reuse",score:Number(weights.giftCardReuse||45),detail:{distinctUsers:Number(giftReuse?.users||0)}});
  const selfPurchase=await db.prepare(`SELECT COUNT(*) n FROM commerce_order_items oi JOIN products p ON p.id=oi.product_id JOIN editions e ON e.id=p.edition_id JOIN publishing_accounts pa ON pa.publisher_id=e.publisher_id JOIN publishing_account_members pam ON pam.account_id=pa.id AND pam.user_id=? AND pam.status='active' WHERE oi.order_id=?`).bind(o.user_id,orderId).first<any>();if(Number(selfPurchase?.n||0)>0)signals.push({code:"publisher_self_purchase",score:Number(weights.publisherSelfPurchase||30),detail:{items:Number(selfPurchase?.n||0)}});
  const link=await db.prepare("SELECT MAX(confidence) c FROM retail_account_risk_links WHERE user_id=? AND status='confirmed_abuse'").bind(o.user_id).first<any>();if(Number(link?.c||0)>=.7)signals.push({code:"linked_abuse",score:Number(weights.linkedAbuse||45),detail:{confidence:Number(link.c)}});
  const accountHold=await db.prepare("SELECT id,reason_code FROM risk_holds WHERE domain='buyer' AND subject_type='user' AND subject_id=? AND hold_scope='account' AND status='active' LIMIT 1").bind(o.user_id).first<any>();if(accountHold)signals.push({code:"active_account_hold",score:Number(weights.activeAccountHold||80),detail:{holdId:accountHold.id,reasonCode:accountHold.reason_code}});
  if(provider?.riskLevel==="highest"||Number(provider?.riskScore||0)>=75)signals.push({code:"processor_high_risk",score:Number(weights.processorHighRisk||55),detail:{riskScore:provider?.riskScore||null,riskLevel:provider?.riskLevel||null}});
  const a=await persistAssessment(db,"buyer","order",orderId,signals,{userId:o.user_id,totalMinor:Number(o.total_minor||0),giftCardMinor:Number(o.gift_card_minor||0),promoDiscountMinor:Number(o.promo_discount_minor||0)},{stripe:provider||{}});
  await db.prepare("UPDATE commerce_orders SET risk_assessment_id=?,risk_action=?,risk_score=?,risk_level=?,updated_at=? WHERE id=?").bind(a.id,a.action,a.score,a.level,now(),orderId).run();
  await recordRiskEvent(db,{domain:"buyer",eventType:provider?"processor_risk_update":"checkout_assessed",subjectType:"order",subjectId:orderId,userId:String(o.user_id),orderId,amountMinor:Number(o.total_minor||0),currency:String(o.currency||""),territory:String(o.territory_code||""),provider:provider?"stripe":"fore",providerEventId:provider?.providerSignalId||"",metadata:{score:a.score,action:a.action},dedupeKey:`buyer-assessment:${a.id}`});
  if(a.action==="hold")await createRiskHold(db,a,"checkout","BUYER_RISK_REVIEW",{amountMinor:Number(o.total_minor||0),currency:String(o.currency),summary:`Order ${o.invoice_number} requires fraud review before capture/fulfillment.`});
  if(a.action==="block")await createRiskHold(db,a,"checkout","BUYER_RISK_BLOCK",{amountMinor:Number(o.total_minor||0),currency:String(o.currency),summary:`Order ${o.invoice_number} was blocked by the active buyer-risk policy.`});return a;
}

export async function assessAccountTakeoverRisk(db:CatalogDB,userId:string,reason="security_event") {
  const policy=await activePolicy(db,"buyer"),w=policy.policy.weights||{},signals:Signal[]=[];
  const sensitive=await db.prepare(`SELECT COUNT(*) n FROM account_security_events WHERE user_id=? AND event_type IN ('email_change_requested','password_changed','mfa_factor_removed','passkey_deleted','other_sessions_revoked') AND created_at>=datetime('now','-1 hour')`).bind(userId).first<any>();
  if(Number(sensitive?.n||0)>=4)signals.push({code:"security_change_burst",score:Number(w.securityChangeBurst||55),detail:{events:Number(sensitive?.n||0)}});
  const countries=await db.prepare("SELECT COUNT(DISTINCT ip_country) n FROM account_security_events WHERE user_id=? AND event_type='login_succeeded' AND ip_country<>'' AND created_at>=datetime('now','-1 day')").bind(userId).first<any>();
  if(Number(countries?.n||0)>=3)signals.push({code:"country_velocity",score:Number(w.countryVelocity||45),detail:{countries:Number(countries?.n||0)}});
  const a=await persistAssessment(db,"buyer","user",userId,signals,{reason,sensitiveChangesLastHour:Number(sensitive?.n||0),loginCountriesLastDay:Number(countries?.n||0)});
  await recordRiskEvent(db,{domain:"buyer",eventType:"account_security_assessed",subjectType:"user",subjectId:userId,userId,metadata:{reason,score:a.score,action:a.action},dedupeKey:`account-security-assessment:${a.id}`});
  if(["hold","block"].includes(a.action))await createRiskHold(db,a,"account","ACCOUNT_TAKEOVER_REVIEW",{summary:"Account-security activity requires manual fraud review before new commerce fulfillment."});
  return a;
}

export async function ingestStripeRiskSignal(db:CatalogDB,orderId:string,charge:any,eventId:string){
  const riskScore=charge?.outcome?.risk_score==null?null:Number(charge.outcome.risk_score),riskLevel=charge?.outcome?.risk_level?String(charge.outcome.risk_level):null,payload={riskScore,riskLevel,networkStatus:charge?.outcome?.network_status||null,sellerMessage:charge?.outcome?.seller_message||null,type:charge?.outcome?.type||null};
  await db.prepare("INSERT OR IGNORE INTO risk_provider_signals(id,provider,provider_signal_id,subject_type,subject_id,signal_type,score,level,payload_hash,normalized_json,created_at) VALUES(?,'stripe',?,'order',?,'radar_charge',?,?,?,?,?,?)").bind(uid("risk_ps"),eventId,orderId,riskScore,riskLevel||"",await sha256(JSON.stringify(payload)),JSON.stringify(payload),now()).run();return assessBuyerOrderRisk(db,orderId,{riskScore,riskLevel,providerSignalId:eventId});
}

export async function assessPublisherRisk(db:CatalogDB,accountId:string,reason="periodic"){
  const arow=await db.prepare("SELECT * FROM publishing_accounts WHERE id=?").bind(accountId).first<any>();if(!arow)throw new ApiError(404,"Publishing account not found.");const weights=(await activePolicy(db,"publisher")).policy.weights||{},signals:Signal[]=[];
  const identityStatus=String(arow.identity_status||"not_started"),taxStatus=String(arow.tax_status||"not_started"),payoutStatus=String(arow.payout_status||"not_started");
  if(["failed","rejected","expired","blocked"].includes(identityStatus))signals.push({code:"identity_unverified",score:Number(weights.identityUnverified||40),detail:{status:identityStatus}});else if(identityStatus==="pending")signals.push({code:"identity_pending",score:5,detail:{status:identityStatus}});
  if(["failed","rejected","expired","blocked"].includes(taxStatus))signals.push({code:"tax_unverified",score:Number(weights.taxUnverified||25),detail:{status:taxStatus}});else if(taxStatus==="pending")signals.push({code:"tax_pending",score:3,detail:{status:taxStatus}});
  if(["failed","rejected","expired","blocked"].includes(payoutStatus))signals.push({code:"payout_unverified",score:Number(weights.payoutUnverified||25),detail:{status:payoutStatus}});else if(payoutStatus==="pending")signals.push({code:"payout_pending",score:3,detail:{status:payoutStatus}});
  const dup=await db.prepare("SELECT COUNT(*) n FROM publishing_duplicate_matches d JOIN publishing_asset_versions v ON v.id=d.asset_version_id JOIN publishing_assets pa ON pa.id=v.asset_id JOIN publishing_edition_drafts e ON e.id=pa.edition_id JOIN publishing_titles t ON t.id=e.title_id WHERE t.account_id=? AND d.disposition IN ('fraud_hold','infringing')").bind(accountId).first<any>();if(Number(dup?.n||0)>0)signals.push({code:"duplicate_content",score:Number(weights.duplicateContent||45),detail:{count:Number(dup.n)}});
  const links=await db.prepare("SELECT COUNT(*) n,MAX(score) c FROM publishing_account_risk_links WHERE account_a_id=? OR account_b_id=?").bind(accountId,accountId).first<any>();const cluster=await db.prepare("SELECT COUNT(*) n,MAX(c.risk_score) c FROM publishing_risk_cluster_members m JOIN publishing_risk_clusters c ON c.id=m.cluster_id WHERE m.account_id=? AND c.status='confirmed_fraud'").bind(accountId).first<any>();if(Number(cluster?.n||0)>0||Number(links?.c||0)>=80)signals.push({code:"confirmed_risk_link",score:Number(weights.confirmedRiskLink||55),detail:{links:Number(links?.n||0),maxScore:Math.max(Number(links?.c||0),Number(cluster?.c||0))}});
  const identityMatches=await db.prepare("SELECT COUNT(*) n,COALESCE(MAX(similarity_score),0) max_score FROM publishing_identity_similarity_matches WHERE account_id=? AND status IN ('review','impersonation') AND similarity_score>=90").bind(accountId).first<any>();if(Number(identityMatches?.n||0)>0)signals.push({code:"identity_similarity",score:Math.min(60,Math.max(30,Number(identityMatches?.max_score||0)-50)),detail:{matches:Number(identityMatches?.n||0),maxSimilarity:Number(identityMatches?.max_score||0)}});
  const payoutReuse=await db.prepare(`SELECT COUNT(DISTINCT other.account_id) n FROM publishing_payout_accounts mine JOIN publishing_payout_accounts other ON other.provider=mine.provider AND other.provider_account_id=mine.provider_account_id AND other.account_id<>mine.account_id WHERE mine.account_id=? AND mine.provider_account_id<>'' AND mine.status IN ('pending','verified') AND other.status IN ('pending','verified')`).bind(accountId).first<any>();if(Number(payoutReuse?.n||0)>0)signals.push({code:"payout_destination_reuse",score:Number(weights.payoutDestinationReuse||45),detail:{otherAccounts:Number(payoutReuse?.n||0)}});
  const sanctions=await db.prepare("SELECT COUNT(*) n FROM moderation_sanctions WHERE publishing_account_id=? AND status='active'").bind(accountId).first<any>().catch(()=>null);if(Number(sanctions?.n||0)>0)signals.push({code:"active_sanction",score:Number(weights.activeSanction||60),detail:{count:Number(sanctions.n)}});
  const asmt=await persistAssessment(db,"publisher","publishing_account",accountId,signals,{identityStatus:arow.identity_status,taxStatus:arow.tax_status,payoutStatus:arow.payout_status,status:arow.status,reason});await db.prepare("UPDATE publishing_accounts SET risk_score=?,risk_level=?,updated_at=? WHERE id=?").bind(asmt.score,asmt.level,now(),accountId).run();await recordRiskEvent(db,{domain:"publisher",eventType:"account_assessed",subjectType:"publishing_account",subjectId:accountId,publishingAccountId:accountId,metadata:{reason,score:asmt.score,action:asmt.action},dedupeKey:`publisher-assessment:${asmt.id}`});if(["hold","block"].includes(asmt.action))await createRiskHold(db,asmt,"publishing",asmt.action==="block"?"PUBLISHER_RISK_BLOCK":"PUBLISHER_RISK_REVIEW",{publishingAccountId:accountId,summary:`Publisher risk assessment requires ${asmt.action} (${reason}).`});return asmt;
}

export async function assessUsageRisk(db:CatalogDB,usageEventId:string){const u=await db.prepare("SELECT * FROM finance_usage_events WHERE id=?").bind(usageEventId).first<any>();if(!u)throw new ApiError(404,"Usage event not found.");const w=(await activePolicy(db,"usage")).policy.weights||{},signals:Signal[]=[];if(u.user_id){const recent=await db.prepare("SELECT COUNT(*) n,COALESCE(SUM(pages_read),0) pages,COALESCE(SUM(seconds_consumed),0) secs FROM finance_usage_events WHERE user_id=? AND occurred_at>=datetime(?,'-1 hour')").bind(u.user_id,u.occurred_at).first<any>();if(Number(recent?.n||0)>60)signals.push({code:"velocity",score:Number(w.velocity||45),detail:{events:Number(recent.n)}});if(Number(recent?.pages||0)>2500||Number(recent?.secs||0)>18000)signals.push({code:"impossible_consumption",score:Number(w.impossibleConsumption||60),detail:{pages:Number(recent?.pages||0),seconds:Number(recent?.secs||0)}});const linked=await db.prepare("SELECT COUNT(*) n,MAX(confidence) c FROM retail_account_risk_links WHERE user_id=? AND status='confirmed_abuse'").bind(u.user_id).first<any>();if(Number(linked?.n||0)>0)signals.push({code:"linked_accounts",score:Number(w.linkedAccounts||40),detail:{links:Number(linked?.n||0),confidence:Number(linked?.c||0)}});}if(u.device_fingerprint_hash){const shared=await db.prepare("SELECT COUNT(DISTINCT user_id) users,COUNT(*) events FROM finance_usage_events WHERE device_fingerprint_hash=? AND user_id IS NOT NULL AND occurred_at>=datetime(?,'-1 day')").bind(u.device_fingerprint_hash,u.occurred_at).first<any>();if(Number(shared?.users||0)>=5)signals.push({code:"repeated_source",score:Number(w.repeatedSource||55),detail:{source:"device",distinctUsers:Number(shared?.users||0),events:Number(shared?.events||0)}});}if(u.network_fingerprint_hash){const network=await db.prepare("SELECT COUNT(DISTINCT user_id) users,COUNT(*) events FROM finance_usage_events WHERE network_fingerprint_hash=? AND user_id IS NOT NULL AND occurred_at>=datetime(?,'-1 day')").bind(u.network_fingerprint_hash,u.occurred_at).first<any>();if(Number(network?.users||0)>=12)signals.push({code:"shared_network_farm",score:Number(w.linkedAccounts||40),detail:{distinctUsers:Number(network?.users||0),events:Number(network?.events||0)}});}const a=await persistAssessment(db,"usage","usage_event",usageEventId,signals,{userId:u.user_id,productId:u.product_id,pages:Number(u.pages_read||0),seconds:Number(u.seconds_consumed||0),deviceFingerprintHash:u.device_fingerprint_hash||"",networkFingerprintHash:u.network_fingerprint_hash||""});await recordRiskEvent(db,{domain:"usage",eventType:"usage_assessed",subjectType:"usage_event",subjectId:usageEventId,userId:u.user_id||null,usageEventId,deviceFingerprintHash:u.device_fingerprint_hash||"",networkFingerprintHash:u.network_fingerprint_hash||"",metadata:{score:a.score,action:a.action,signals:signals.map(x=>x.code)},dedupeKey:`usage-assessment:${a.id}`,occurredAt:u.occurred_at});if(["hold","block"].includes(a.action))await createRiskHold(db,a,"usage_credit","SUSPICIOUS_USAGE",{summary:"Subscription/library usage is held from royalty credit pending review."});return a;}

export async function assessPayoutRisk(db:CatalogDB,payoutItemId:string){const item=await db.prepare(`SELECT pi.*,fp.publisher_id,pa.id publishing_account_id,pa.risk_score publisher_risk_score,pa.risk_level publisher_risk_level,pa.tax_status,pa.payout_status FROM payout_items pi JOIN finance_parties fp ON fp.id=pi.party_id LEFT JOIN publishing_accounts pa ON pa.finance_party_id=fp.id WHERE pi.id=?`).bind(payoutItemId).first<any>();if(!item)throw new ApiError(404,"Payout item not found.");const w=(await activePolicy(db,"payout")).policy.weights||{},signals:Signal[]=[];if(Number(item.publisher_risk_score||0)>=60)signals.push({code:"publisher_risk",score:Number(w.publisherRisk||60),detail:{score:Number(item.publisher_risk_score)}});if(item.publishing_account_id&&item.tax_status!=="verified")signals.push({code:"tax_not_verified",score:Number(w.taxNotVerified||60),detail:{status:item.tax_status}});if(item.publishing_account_id&&item.payout_status!=="verified")signals.push({code:"payout_not_verified",score:Number(w.payoutNotVerified||60),detail:{status:item.payout_status}});const rights=await db.prepare("SELECT 1 ok FROM finance_royalty_allocations WHERE status='held' AND id IN (SELECT royalty_allocation_id FROM payout_allocation_links WHERE payout_item_id=?) LIMIT 1").bind(payoutItemId).first<any>();if(rights)signals.push({code:"rights_hold",score:Number(w.rightsHold||70)});const a=await persistAssessment(db,"payout","payout_item",payoutItemId,signals,{partyId:item.party_id,netMinor:Number(item.net_minor||0),publishingAccountId:item.publishing_account_id||null});await db.prepare("UPDATE payout_items SET risk_assessment_id=?,status=CASE WHEN ? IN ('hold','block') THEN 'held' ELSE status END,hold_reason_code=CASE WHEN ? IN ('hold','block') THEN 'RISK_REVIEW' ELSE hold_reason_code END WHERE id=?").bind(a.id,a.action,a.action,payoutItemId).run();if(["hold","block"].includes(a.action))await createRiskHold(db,a,"payout","PAYOUT_RISK_REVIEW",{amountMinor:Number(item.net_minor||0),currency:String(item.currency),publishingAccountId:item.publishing_account_id||null,summary:"Royalty payout held pending fraud/compliance investigation."});return a;}

export async function releaseRiskHold(db:CatalogDB,staffUserId:string,raw:unknown){const x=z.object({holdId:z.string().min(1),note:z.string().trim().min(3).max(4000)}).parse(raw),h=await db.prepare("SELECT * FROM risk_holds WHERE id=?").bind(x.holdId).first<any>();if(!h)throw new ApiError(404,"Risk hold not found.");if(h.status!=="active")return{id:h.id,status:h.status};if(h.hold_scope==="payout"&&h.subject_type==="payout_item"){const reassessment=await assessPayoutRisk(db,String(h.subject_id));if(["hold","block"].includes(reassessment.action))throw new ApiError(409,"This payout still fails fraud, tax, payout-verification, or rights controls and cannot be released.");}const at=now();await db.prepare("UPDATE risk_holds SET status='released',released_at=?,released_by_user_id=?,release_note=? WHERE id=?").bind(at,staffUserId,x.note,h.id).run();if(h.hold_scope==="payout"&&h.subject_type==="payout_item")await db.prepare("UPDATE payout_items SET status='pending',hold_reason_code='' WHERE id=? AND status='held'").bind(h.subject_id).run();await db.prepare("INSERT INTO risk_case_events(id,case_id,event_type,actor_type,actor_user_id,payload_json,created_at) SELECT ?,id,'hold_released','staff',?,?,? FROM risk_cases WHERE domain=? AND subject_type=? AND subject_id=? AND status NOT IN ('resolved','closed') ORDER BY opened_at DESC LIMIT 1").bind(uid("risk_ce"),staffUserId,JSON.stringify({holdId:h.id,note:x.note}),at,h.domain,h.subject_type,h.subject_id).run();return{id:h.id,status:"released"};}

export async function manageRiskCase(db:CatalogDB,staffUserId:string,raw:unknown){const x=z.object({caseId:z.string().min(1),status:z.enum(["open","triage","in_review","waiting_external","actioned","resolved","closed"]).optional(),assignedToUserId:z.string().nullable().optional(),disposition:z.enum(["legitimate","abuse_confirmed","fraud_confirmed","insufficient_evidence","referred","false_positive"]).optional(),note:z.string().max(5000).default("")}).parse(raw),c=await db.prepare("SELECT * FROM risk_cases WHERE id=?").bind(x.caseId).first<any>();if(!c)throw new ApiError(404,"Risk case not found.");const at=now(),status=x.status||c.status,resolved=["resolved","closed"].includes(status)?at:null;await db.prepare("UPDATE risk_cases SET status=?,assigned_to_user_id=COALESCE(?,assigned_to_user_id),disposition=CASE WHEN ?<>'' THEN ? ELSE disposition END,updated_at=?,resolved_at=COALESCE(?,resolved_at) WHERE id=?").bind(status,x.assignedToUserId??null,x.disposition||"",x.disposition||"",at,resolved,x.caseId).run();await db.prepare("INSERT INTO risk_case_events(id,case_id,event_type,actor_type,actor_user_id,payload_json,created_at) VALUES(?,?,'case_updated','staff',?,?,?)").bind(uid("risk_ce"),x.caseId,staffUserId,JSON.stringify({status,assignedToUserId:x.assignedToUserId,disposition:x.disposition,note:x.note}),at).run();return{id:x.caseId,status,disposition:x.disposition||c.disposition};}

export async function upsertRiskEntityLink(db:CatalogDB,raw:unknown){const x=z.object({sourceType:z.string().min(1).max(60),sourceId:z.string().min(1).max(240),targetType:z.string().min(1).max(60),targetId:z.string().min(1).max(240),linkType:z.enum(["device","network","payment","identity","payout_destination","content","household","behavioral","manual"]),confidence:z.number().min(0).max(1),evidenceHash:z.string().max(128).default(""),evidence:z.record(z.string(),z.unknown()).default({}),status:z.enum(["active","dismissed","confirmed_abuse"]).default("active")}).parse(raw),at=now(),id=uid("risk_link");await db.prepare(`INSERT INTO risk_entity_links(id,source_type,source_id,target_type,target_id,link_type,confidence,evidence_hash,evidence_json,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(source_type,source_id,target_type,target_id,link_type) DO UPDATE SET confidence=excluded.confidence,evidence_hash=excluded.evidence_hash,evidence_json=excluded.evidence_json,status=excluded.status,updated_at=excluded.updated_at`).bind(id,x.sourceType,x.sourceId,x.targetType,x.targetId,x.linkType,x.confidence,x.evidenceHash,JSON.stringify(x.evidence),x.status,at,at).run();return{saved:true};}

export async function createRiskPolicyVersion(db:CatalogDB,userId:string,raw:unknown){const x=z.object({domain:z.enum(["buyer","publisher","community","payout","usage"]),policy:z.record(z.string(),z.unknown()),effectiveFrom:z.string().datetime().optional()}).parse(raw),at=now(),canonical=JSON.stringify(x.policy),hash=await sha256(canonical),next=Number((await db.prepare("SELECT COALESCE(MAX(version),0)+1 n FROM risk_policy_versions WHERE domain=?").bind(x.domain).first<any>())?.n||1),id=`risk-${x.domain}-v${next}`;await db.prepare("UPDATE risk_policy_versions SET status='retired',effective_to=? WHERE domain=? AND status='active' AND effective_to IS NULL").bind(x.effectiveFrom||at,x.domain).run();await db.prepare("INSERT INTO risk_policy_versions(id,domain,version,status,policy_json,policy_hash,effective_from,created_by_user_id,created_at) VALUES(?,?,?,'active',?,?,?,?,?)").bind(id,x.domain,next,canonical,hash,x.effectiveFrom||at,userId,at).run();return{id,version:next,policyHash:hash};}

